// Onboarding PME de construction : champs structurés nécessaires pour reprendre
// une entreprise existante sans détourner les notes libres.

const onboardingCompanyFields=[
 ['vatRegime','Régime TVA'],['vatFrequency','Fréquence des déclarations TVA'],['accountingStart','Début de l’exercice comptable','date'],['accountingEnd','Fin de l’exercice comptable','date'],
 ['previousRevenue','CA exercice précédent HTVA','number'],['currentRevenue','CA actuel HTVA','number'],['revenueTarget','Objectif annuel HTVA','number'],['openingStock','Stock initial valorisé','number'],
 ['openingReceivables','Créances clients initiales','number'],['openingSupplierDebt','Dettes fournisseurs initiales','number'],['openingBank','Solde compte courant','number'],['openingReserve','Solde compte réserve','number'],
 ['openingCash','Caisse','number'],['openingLoans','Emprunts restant dus','number'],['openingLeases','Leasings restant dus','number'],['openingFixedAssets','Immobilisations comptables','number']
];
if(!fieldGroups.some(([label])=>label==='Comptabilité & situation de départ'))fieldGroups.push(['Comptabilité & situation de départ',onboardingCompanyFields]);

function onboardingPersonFields(form,person){
  if(!form||form.querySelector('.onboarding-hr-fields'))return;
  const hr=person?.employment||{};
  const section=document.createElement('details');section.className='onboarding-hr-fields';section.innerHTML=`<summary>Emploi, paie & coût interne</summary><div class="form-two">
    <label>Statut<select name="staffType">${['Dirigeant indépendant','Employé','Ouvrier','Apprenti','Stagiaire','Intérimaire'].map(v=>`<option ${v===(hr.staffType||person?.category)?'selected':''}>${v}</option>`).join('')}</select></label>
    <label>Commission paritaire<input name="jointCommittee" value="${esc(hr.jointCommittee||'')}" placeholder="CP 124, CP 200…"></label>
    <label>Catégorie barémique<input name="wageCategory" value="${esc(hr.wageCategory||'')}"></label>
    <label>Ancienneté reconnue (années)<input name="seniorityYears" type="number" min="0" step="0.1" value="${Number(hr.seniorityYears||0)}"></label>
    <label>Salaire brut mensuel (€)<input name="grossMonthly" type="number" min="0" step="0.01" value="${Number(hr.grossMonthly||0)}"></label>
    <label>Salaire brut horaire (€)<input name="grossHourly" type="number" min="0" step="0.01" value="${Number(hr.grossHourly||0)}"></label>
    <label>Coût employeur horaire (€)<input name="employerHourly" type="number" min="0" step="0.01" value="${Number(hr.employerHourly||0)}"></label>
    <label>Coût interne horaire (€)<input name="internalHourly" type="number" min="0" step="0.01" value="${Number(hr.internalHourly||0)}"></label>
    <label>Temps de travail (h/semaine)<input name="weeklyHours" type="number" min="0" max="80" step="0.5" value="${Number(hr.weeklyHours||0)}"></label>
    <label>Horaire habituel<input name="usualSchedule" value="${esc(hr.usualSchedule||'')}"></label>
    <label>Secrétariat social<input name="socialOffice" value="${esc(hr.socialOffice||company.socialOffice||'')}"></label>
    <label>Référence paie<input name="payrollReference" value="${esc(hr.payrollReference||'')}"></label>
  </div>`;
  form.querySelector('.modal-actions')?.before(section);
  const identity=form.querySelector('[name="name"]')?.closest('.form-two');if(identity)form.prepend(identity);
}
function onboardingPersonForm(id=0){personEditForm(id);onboardingPersonFields(document.querySelector('#modalbody form'),getPerson(id))}
personForm=function(id){if(id)return showPersonDossier(id);return onboardingPersonForm(0)};
const savePersonBeforeOnboarding=savePerson;
savePerson=function(event,id){const f=new FormData(event.target),employment={staffType:f.get('staffType')||'',jointCommittee:f.get('jointCommittee')?.trim()||'',wageCategory:f.get('wageCategory')?.trim()||'',seniorityYears:+f.get('seniorityYears')||0,grossMonthly:+f.get('grossMonthly')||0,grossHourly:+f.get('grossHourly')||0,employerHourly:+f.get('employerHourly')||0,internalHourly:+f.get('internalHourly')||0,weeklyHours:+f.get('weeklyHours')||0,usualSchedule:f.get('usualSchedule')?.trim()||'',socialOffice:f.get('socialOffice')?.trim()||'',payrollReference:f.get('payrollReference')?.trim()||''};savePersonBeforeOnboarding(event,id);if(document.querySelector('#modal').open)return;const person=id?getPerson(id):people.at(-1);if(person){person.employment=employment;if(employment.staffType)person.category=employment.staffType==='Dirigeant indépendant'?'Dirigeant':employment.staffType}render()};
const showPersonBeforeOnboarding=showPersonDossier;showPersonDossier=function(id){showPersonBeforeOnboarding(id);const person=getPerson(id),root=document.querySelector('#modalbody');if(!person||!root)return;root.querySelectorAll('button[onclick*="personEditForm"]').forEach(button=>button.setAttribute('onclick',`onboardingPersonForm(${id})`));const hr=person.employment||{};root.querySelector('.professional-summary')?.insertAdjacentHTML('afterend',`<section class="professional-summary"><div><small>Commission</small><strong>${esc(hr.jointCommittee||'—')}</strong></div><div><small>Catégorie</small><strong>${esc(hr.wageCategory||'—')}</strong></div><div><small>Temps</small><strong>${hr.weeklyHours?hr.weeklyHours+' h/semaine':'—'}</strong></div><div><small>Coût interne</small><strong>${hr.internalHourly?money(hr.internalHourly)+'/h':'—'}</strong></div></section>`)};

// Véhicules : la catégorie choisie pilote réellement le groupe et ouvre les champs dédiés.
assetForm=function(id){if(typeof canFieldAction==='function'&&!canFieldAction('manageAssets'))return denyAccess('Vous ne pouvez pas gérer les biens.');const a=assets.find(x=>x.id===id)||{name:'',group:assetCategory==='vehicles'?'vehicles':'tools',category:assetCategory==='vehicles'?'Camionnette équipée':'Machine',mode:'Achat',condition:'En service',provider:'',reference:'',start:reference,end:'',monthly:0,responsible:'',attached:'',contents:'',purchasePrice:0,currentValue:0,vehicle:null},v=a.vehicle||{};const input=(name,label,type='text',value='')=>`<label>${label}<input name="${name}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${esc(value)}"></label>`;modal(id?'Modifier le dossier':'Ajouter un bien',`<form onsubmit="saveOnboardingAsset(event,${id||0})"><label>Nom du bien / véhicule<input name="name" required value="${esc(a.name)}"></label><div class="form-two">
  <label>Famille<select name="group" onchange="document.querySelector('#onboardingVehicle').hidden=this.value!=='vehicles'"><option value="vehicles" ${a.group==='vehicles'?'selected':''}>Véhicule</option><option value="tools" ${a.group==='tools'?'selected':''}>Matériel / outillage</option></select></label>
  <label>Type<input name="category" required value="${esc(a.category)}"></label><label>Financement<select name="mode">${['Achat','Leasing','Location','Mise à disposition'].map(x=>`<option ${x===a.mode?'selected':''}>${x}</option>`).join('')}</select></label>
  <label>État<select name="condition">${['En service','À contrôler','À réparer','En réparation','Hors service'].map(x=>`<option ${x===a.condition?'selected':''}>${x}</option>`).join('')}</select></label>
  ${input('provider','Fournisseur / financeur','text',a.provider)}${input('reference','N° interne / contrat','text',a.reference)}${input('start','Date d’achat / début','date',a.start)}${input('end','Financement / location jusqu’au','date',a.end)}${input('monthly','Mensualité HT (€)','number',a.monthly)}${input('purchasePrice','Prix d’achat HT (€)','number',a.purchasePrice)}${input('currentValue','Valeur actuelle (€)','number',a.currentValue)}${input('responsible','Responsable','text',a.responsible)}
  </div>${input('attached','Affectation / chantier actuel','text',a.attached)}<label>Contenu / remarques<textarea name="contents">${esc(a.contents||'')}</textarea></label>
  <fieldset id="onboardingVehicle" ${a.group!=='vehicles'?'hidden':''}><legend>Fiche véhicule</legend><div class="form-two">${input('registration','Immatriculation','text',v.registration)}${input('model','Marque / modèle','text',v.model)}${input('year','Année','number',v.year)}<label>Carburant<select name="fuel">${['Diesel','Essence','Hybride','Électrique','Autre'].map(value=>`<option ${String(v.fuel||'Diesel').toLowerCase()===value.toLowerCase()?'selected':''}>${value}</option>`).join('')}</select></label>${input('firstRegistration','Première immatriculation','date',v.firstRegistration)}${input('mileage','Kilométrage','number',v.mileage)}${input('lastService','Dernier entretien','date',v.lastService)}${input('nextService','Prochain entretien','date',v.nextService)}${input('inspection','Contrôle technique','date',v.inspection)}${input('insurer','Assureur','text',v.insurer)}${input('policy','Police','text',v.policy)}${input('insuranceEnd','Échéance assurance','date',v.insuranceEnd)}${input('tyres','Pneus / échéance','text',v.tyres)}${input('mainDriver','Conducteur principal','text',v.mainDriver)}</div></fieldset>
  <p id="assetError" class="form-error"></p><div class="modal-actions"><button class="btn primary">Enregistrer le dossier</button></div></form>`)};
function saveOnboardingAsset(event,id){event.preventDefault();const f=new FormData(event.target),group=f.get('group'),data={name:f.get('name').trim(),group,category:f.get('category').trim(),mode:f.get('mode'),condition:f.get('condition'),provider:f.get('provider').trim(),reference:f.get('reference').trim(),start:f.get('start'),end:f.get('end'),monthly:+f.get('monthly')||0,purchasePrice:+f.get('purchasePrice')||0,currentValue:+f.get('currentValue')||0,responsible:f.get('responsible').trim(),attached:f.get('attached').trim(),contents:f.get('contents').trim(),vehicle:null};if(!data.name||!data.category||!data.responsible){document.querySelector('#assetError').textContent='Nom, type et responsable sont obligatoires.';return}if(group==='vehicles')data.vehicle={registration:f.get('registration').trim(),model:f.get('model').trim(),year:+f.get('year')||0,fuel:f.get('fuel').trim(),firstRegistration:f.get('firstRegistration'),mileage:+f.get('mileage')||0,lastService:f.get('lastService'),nextService:f.get('nextService'),inspection:f.get('inspection'),insurer:f.get('insurer').trim(),policy:f.get('policy').trim(),insuranceEnd:f.get('insuranceEnd'),tyres:f.get('tyres').trim(),mainDriver:f.get('mainDriver').trim()};let a=assets.find(x=>x.id===id);if(a){a.history??=[];a.history.push({date:reference,text:'Dossier mis à jour.'});Object.assign(a,data)}else{a={id:Date.now(),...data,history:[{date:reference,text:'Dossier créé.'}],docs:[],fuelEntries:[]};assets.push(a)}if(a.vehicle){syncAssetReminder(a,'inspection',a.vehicle.inspection,'Contrôle technique · '+a.name,'Contrôle technique');syncAssetReminder(a,'insuranceEnd',a.vehicle.insuranceEnd,'Assurance · '+a.name,'Assurance');syncAssetReminder(a,'nextService',a.vehicle.nextService,'Entretien · '+a.name,'Entretien')}closeModal();assetCategory=group;render();showAsset(a.id);toast(group==='vehicles'?'Véhicule enregistré dans la flotte.':'Matériel enregistré.')}

// Reprise d’un chantier déjà commencé.
jobForm=function(id=0){const j=jobs.find(x=>String(x.id)===String(id))||{reference:'',name:'',client:'',town:'',address:'',type:'',phase:'À préparer',progress:0,contractAmount:0,responsibleId:0,teamIds:[],plannedMonths:0,finance:{plannedHours:0,materialsBudget:0,subcontractingBudget:0,otherBudget:0}};modal(id?'Modifier le chantier':'Importer / créer un chantier',`<form onsubmit="saveOnboardingJob(event,${esc(JSON.stringify(String(id)))})"><div class="form-two"><label>Référence<input name="reference" value="${esc(j.reference||'')}" placeholder="CH-26017"></label><label>Nom<input name="name" required value="${esc(j.name)}"></label><label>Client<input name="client" required list="onboardingClients" value="${esc(j.client)}"></label><label>Commune<input name="town" value="${esc(j.town)}"></label><label>Adresse<input name="address" value="${esc(j.address)}"></label><label>Type de travaux<input name="type" required value="${esc(j.type||'')}"></label><label>État<select name="phase">${['À préparer','En cours','Suspendu','Terminé'].map(x=>`<option ${x===j.phase?'selected':''}>${x}</option>`).join('')}</select></label><label>Avancement (%)<input name="progress" type="number" min="0" max="100" value="${Number(j.progress||0)}"></label><label>Montant contrat HTVA (€)<input name="contractAmount" type="number" min="0" step="0.01" value="${Number(j.contractAmount||0)}"></label><label>Durée prévue (mois)<input name="plannedMonths" type="number" min="0" step="0.5" value="${Number(j.plannedMonths||0)}"></label><label>Responsable<select name="responsibleId"><option value="0">À définir</option>${people.map(p=>`<option value="${p.id}" ${p.id===j.responsibleId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Heures budgétées<input name="plannedHours" type="number" min="0" step="0.5" value="${Number(j.finance?.plannedHours||0)}"></label><label>Budget main-d’œuvre (€)<input name="labourBudget" type="number" min="0" step="0.01" value="${Number(j.finance?.labourBudget||0)}"></label><label>Budget matériaux (€)<input name="materialsBudget" type="number" min="0" step="0.01" value="${Number(j.finance?.materialsBudget||0)}"></label><label>Budget sous-traitance (€)<input name="subcontractingBudget" type="number" min="0" step="0.01" value="${Number(j.finance?.subcontractingBudget||0)}"></label><label>Autres / imprévus (€)<input name="otherBudget" type="number" min="0" step="0.01" value="${Number(j.finance?.otherBudget||0)}"></label></div><fieldset><legend>Équipes prévues</legend><div class="check-people">${teams.map(t=>`<label><input type="checkbox" name="teamIds" value="${t.id}" ${(j.teamIds||[]).includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')||'<p class="subtle">Créez d’abord les équipes si nécessaire.</p>'}</div></fieldset><datalist id="onboardingClients">${contacts.filter(c=>c.roles?.includes('Client')).map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist><div class="modal-actions"><button class="btn primary">Enregistrer le chantier</button></div></form>`)};
function saveOnboardingJob(event,id){event.preventDefault();const f=new FormData(event.target),finance={...(jobs.find(x=>String(x.id)===String(id))?.finance||{materials:0,subcontracting:0,other:0,adjustments:[],hourlyCost:0}),plannedHours:+f.get('plannedHours')||0,labourBudget:+f.get('labourBudget')||0,materialsBudget:+f.get('materialsBudget')||0,subcontractingBudget:+f.get('subcontractingBudget')||0,otherBudget:+f.get('otherBudget')||0},data={reference:f.get('reference').trim(),name:f.get('name').trim(),client:f.get('client').trim(),town:f.get('town').trim(),address:f.get('address').trim(),type:f.get('type').trim(),workType:f.get('type').trim(),phase:f.get('phase'),progress:Math.max(0,Math.min(100,+f.get('progress')||0)),contractAmount:+f.get('contractAmount')||0,plannedMonths:+f.get('plannedMonths')||0,responsibleId:+f.get('responsibleId')||0,teamIds:f.getAll('teamIds').map(Number),finance};if(!data.name||!data.client||!data.type)return;if(event.target.dataset.commercialJob)return commercialSaveJob(event,id,data);let job=jobs.find(x=>String(x.id)===String(id));if(job){Object.assign(job,data);ensureBlankRecords()}else{job={id:Math.max(0,...jobs.map(x=>Number(x.id)||0))+1,...data,color:'purple',required:[],photos:[],execution:[],materials:[],contacts:[],notes:[],documents:[],timeEntries:[],dailyChecks:{}};jobs.push(job)}closeModal();render();toast('Chantier et situation initiale enregistrés.')}

// Prix d’achat, coût rendu et prix de vente coexistent sur une même référence.
catalogueForm=function(id=''){const x=priceCatalog.find(item=>item.id===id)||{name:'',category:'Matériaux',unit:'unité',purchasePrice:0,deliveredCost:0,price:0,vat:21,primarySupplier:'',alternativeSuppliers:'',discount:0,description:''};modal(id?'Modifier la référence':'Nouvelle référence',`<form onsubmit="saveOnboardingCatalogue(event,'${id}')"><label>Nom<input name="name" required value="${esc(x.name)}"></label><div class="form-two"><label>Catégorie<input name="category" required value="${esc(x.category)}"></label><label>Unité<select name="unit">${['heure','unité','pièce','m²','m³','mètre courant','kg','litre','sac','plaque','forfait'].map(v=>`<option ${v===x.unit?'selected':''}>${v}</option>`).join('')}</select></label><label>Prix d’achat HTVA<input name="purchasePrice" type="number" min="0" step="0.01" value="${Number(x.purchasePrice??x.price??0)}"></label><label>Coût rendu chantier<input name="deliveredCost" type="number" min="0" step="0.01" value="${Number(x.deliveredCost??x.purchasePrice??x.price??0)}"></label><label>Prix de vente HTVA<input name="price" type="number" min="0" step="0.01" value="${Number(x.price||0)}"></label><label>TVA (%)<select name="vat">${[0,6,12,21].map(v=>`<option ${v===Number(x.vat)?'selected':''}>${v}</option>`).join('')}</select></label><label>Fournisseur principal<input name="primarySupplier" value="${esc(x.primarySupplier||'')}"></label><label>Fournisseurs alternatifs<input name="alternativeSuppliers" value="${esc(Array.isArray(x.alternativeSuppliers)?x.alternativeSuppliers.join(', '):x.alternativeSuppliers||'')}"></label><label>Remise (%)<input name="discount" type="number" min="0" max="100" step="0.01" value="${Number(x.discount||0)}"></label></div><label>Précision<textarea name="description">${esc(x.description||'')}</textarea></label><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)};
function saveOnboardingCatalogue(event,id){event.preventDefault();const f=new FormData(event.target),purchasePrice=+f.get('purchasePrice')||0,deliveredCost=+f.get('deliveredCost')||0,price=+f.get('price')||0,name=f.get('name').trim();if(!name)return;let item=priceCatalog.find(x=>x.id===id);const previous=item?{date:reference,purchasePrice:item.purchasePrice||0,deliveredCost:item.deliveredCost||0,price:item.price||0}:null,data={name,category:f.get('category').trim(),unit:f.get('unit'),purchasePrice,deliveredCost,price,vat:+f.get('vat'),primarySupplier:f.get('primarySupplier').trim(),alternativeSuppliers:f.get('alternativeSuppliers').split(',').map(v=>v.trim()).filter(Boolean),discount:+f.get('discount')||0,description:f.get('description').trim()};if(item){item.priceHistory??=[];if(previous)item.priceHistory.push(previous);Object.assign(item,data)}else priceCatalog.push({id:'work-'+Date.now(),...data,priceHistory:[]});closeModal();quoteArea='catalogue';render();toast('Référence et prix enregistrés.')}

// Factures structurées en HTVA, TVA et TVAC.
invoiceForm=function(){const peppol=typeof electronicInvoiceSettings==='function'&&electronicInvoiceSettings().enabled;modal('Ajouter une facture client',`<form onsubmit="saveOnboardingInvoice(event)"><label>Chantier<select name="job">${jobs.map(j=>`<option value="${j.id}">${esc(j.name)} · ${esc(j.client)}</option>`).join('')}</select></label><div class="form-two"><label>Référence<input name="ref" required></label><label>Date<input name="date" type="date" required value="${reference}"></label><label>Échéance<input name="due" type="date" required value="${reference}"></label><label>Montant HTVA<input name="netAmount" type="number" min="0" step="0.01" required></label><label>Traitement TVA<select name="vatMode"><option value="standard">TVA standard</option><option value="renovation">Rénovation 6 %</option><option value="reverse">Autoliquidation</option><option value="exempt">Exonéré / hors champ</option></select></label><label>Taux TVA<select name="vatRate"><option>21</option><option>6</option><option>12</option><option>0</option></select></label><label>Type client<select name="customerType"><option>B2C</option><option>B2B</option><option>B2G</option></select></label><label>Format<select name="deliveryFormat"><option>PDF / manuel</option><option ${peppol?'':'disabled'}>Peppol</option></select></label><label>Statut<select name="status"><option>À recevoir</option><option>Envoyée</option><option>Acceptée</option><option>Rejetée</option><option>Payée</option></select></label></div><p class="notice">L’enregistrement ne transmet rien au client ni à Peppol.</p><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)};
function saveOnboardingInvoice(event){event.preventDefault();const f=new FormData(event.target),jobId=String(f.get('job')||''),job=jobs.find(j=>String(j.id)===jobId),netAmount=+f.get('netAmount'),vatMode=f.get('vatMode'),vatRate=['reverse','exempt'].includes(vatMode)?0:+f.get('vatRate'),vatAmount=Math.round(netAmount*vatRate)/100,amount=Math.round((netAmount+vatAmount)*100)/100;if(!job||!Number.isFinite(netAmount))return;accountingData.customerInvoices.push({id:Date.now(),ref:f.get('ref').trim(),client:job.client,job:job.id,date:f.get('date'),due:f.get('due'),netAmount,vatMode,vatRate,vatAmount,amount,customerType:f.get('customerType'),deliveryFormat:f.get('deliveryFormat'),structuredStatus:'Non envoyé',status:f.get('status')});closeModal();render();toast('Facture enregistrée sans envoi.')}

supplierBillForm=function(jobId=0){modal('Ajouter une facture fournisseur',`<form onsubmit="saveOnboardingSupplierBill(event)"><div class="form-two"><label>Fournisseur<input name="supplier" required list="onboardingSuppliers"></label><label>Référence<input name="ref"></label><label>Date<input name="date" type="date" required value="${reference}"></label><label>Échéance<input name="due" type="date" required value="${reference}"></label><label>Montant HTVA<input name="netAmount" type="number" min="0.01" step="0.01" required></label><label>TVA (%)<select name="vatRate"><option>21</option><option>6</option><option>12</option><option>0</option></select></label></div><fieldset><legend>Ventilation par chantier (montants HTVA)</legend>${jobs.map(j=>`<label class="detail-row"><span><input type="checkbox" name="allocationJob" value="${j.id}" ${String(j.id)===String(jobId)?'checked':''}> ${esc(j.name)}</span><input name="allocation-${j.id}" type="number" min="0" step="0.01" value="${String(j.id)===String(jobId)?'0':''}" aria-label="Montant pour ${esc(j.name)}"></label>`).join('')||'<p class="subtle">Aucun chantier.</p>'}</fieldset><label>Note<input name="note"></label><datalist id="onboardingSuppliers">${contacts.filter(c=>c.roles?.some(r=>['Fournisseur','Sous-traitant'].includes(r))).map(c=>`<option value="${esc(c.company||c.name)}"></option>`).join('')}</datalist><div class="modal-actions"><button class="btn primary">Enregistrer la facture fournisseur</button></div></form>`)};
function saveOnboardingSupplierBill(event){event.preventDefault();const f=new FormData(event.target),netAmount=+f.get('netAmount'),vatRate=+f.get('vatRate'),vatAmount=Math.round(netAmount*vatRate)/100,amount=Math.round((netAmount+vatAmount)*100)/100,allocations=f.getAll('allocationJob').map(value=>String(value)).map(job=>({job,amount:+f.get('allocation-'+job)||0})).filter(x=>x.amount>0),allocated=allocations.reduce((sum,x)=>sum+x.amount,0);if(!Number.isFinite(netAmount)||netAmount<=0)return;if(allocated>netAmount+.005)return toast('La ventilation chantier dépasse le montant HTVA.');const bill={id:'bill-'+crypto.randomUUID(),supplier:f.get('supplier').trim(),ref:f.get('ref').trim(),date:f.get('date'),due:f.get('due'),netAmount,vatRate,vatAmount,amount,job:allocations[0]?.job||0,allocations,overheadAmount:Math.round((netAmount-allocated)*100)/100,note:f.get('note').trim(),status:'À payer'};accountingData.supplierBills.push(bill);allocations.forEach(allocation=>{const job=jobs.find(item=>String(item.id)===String(allocation.job));if(job){job.finance??={};job.finance.supplierInvoices=Number(job.finance.supplierInvoices||0)+allocation.amount}});closeModal();render();toast('Facture fournisseur et ventilation enregistrées.')}

// Stock initial valorisé et sorties futures reliables à un chantier.
let stockItems=[];const restoreStock=restoreWorkspace;restoreWorkspace=function(state){restoreStock(state);stockItems=Array.isArray(state.stockItems)?state.stockItems:[]};const snapshotStock=workspaceSnapshot;workspaceSnapshot=function(){const state=JSON.parse(snapshotStock());state.stockItems=stockItems;return JSON.stringify(state)};
if(!tabs2.some(([key])=>key==='stock'))tabs2.splice(tabs2.findIndex(([key])=>key==='fleet'),0,['stock','Stock']);
