const savePersonBeforeRemunerationHistory=savePerson;savePerson=function(event,id){const person=id?getPerson(id):null,previous=person?.employment?{grossHourly:Number(person.employment.grossHourly||0),grossMonthly:Number(person.employment.grossMonthly||0),validFrom:person.employment.validFrom||''}:null;savePersonBeforeRemunerationHistory(event,id);const updated=id?getPerson(id):people.at(-1);if(updated?.employment&&previous&&(previous.grossHourly!==Number(updated.employment.grossHourly||0)||previous.grossMonthly!==Number(updated.employment.grossMonthly||0))){updated.employment.remunerationHistory??=[];updated.employment.remunerationHistory.push({...previous,endedAt:reference,changedAt:new Date().toISOString()});updated.employment.validFrom=reference}};
function certificationForm(personId){modal('Certification / formation',`<form onsubmit="saveCertification(event,${personId})"><div class="form-two"><label>Type<input name="type" required placeholder="VCA, premiers secours, nacelle…"></label><label>Organisme<input name="provider"></label><label>Date obtenue<input name="obtained" type="date"></label><label>Expiration éventuelle<input name="expires" type="date"></label><label>Statut<select name="status"><option>Valide</option><option>À renouveler</option><option>Expirée</option><option>En cours</option></select></label><label>Alerte avant expiration (jours)<input name="alertDays" type="number" min="0" value="30"></label></div><label>Document / référence<input name="document"></label><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function saveCertification(event,personId){event.preventDefault();const person=getPerson(personId),f=new FormData(event.target);person.certifications??=[];const certification={id:'cert-'+crypto.randomUUID(),type:f.get('type').trim(),provider:f.get('provider').trim(),obtained:f.get('obtained'),expires:f.get('expires'),status:f.get('status'),alertDays:Number(f.get('alertDays')||0),document:f.get('document').trim()};person.certifications.push(certification);if(certification.expires)reminders.push({id:'cert-reminder-'+crypto.randomUUID(),title:`Certification · ${person.name} · ${certification.type}`,date:certification.expires,kind:'Formation / habilitation',state:'todo',owner:company.adminContact||company.manager||'',note:'Échéance issue du registre structuré des certifications.',linkType:'person',linkId:person.id,sourceField:'certification'});closeModal();render();showPersonDossier(personId);toast('Certification enregistrée avec son échéance.')}
function ppeForm(personId){modal('Remise d’EPI',`<form onsubmit="savePpe(event,${personId})"><div class="form-two"><label>Équipement<select name="type">${['Casque','Chaussures','Harnais','Lunettes','Protections auditives','Vêtements','Autre'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Date remise<input name="issued" type="date" required value="${reference}"></label><label>Quantité<input name="quantity" type="number" min="1" value="1"></label><label>Taille<input name="size"></label><label>Coût<input name="cost" type="number" min="0" step="0.01"></label><label>Renouvellement<input name="renewal" type="date"></label></div><label>Retour éventuel<input name="returned" type="date"></label><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function savePpe(event,personId){event.preventDefault();const person=getPerson(personId),f=new FormData(event.target);person.ppe??=[];person.ppe.push({id:'ppe-'+crypto.randomUUID(),type:f.get('type'),issued:f.get('issued'),quantity:Number(f.get('quantity')||1),size:f.get('size').trim(),cost:Number(f.get('cost')||0),renewal:f.get('renewal'),returned:f.get('returned')});closeModal();render();showPersonDossier(personId);toast('Remise d’EPI enregistrée.')}
function timeRecordForm(personId){modal('Temps / absence structuré',`<form onsubmit="saveTimeRecord(event,${personId})"><div class="form-two"><label>Date<input name="date" type="date" required value="${reference}"></label><label>Type<select name="type">${timeEntryTypes.map(v=>`<option>${v}</option>`).join('')}</select><label>Durée (h)<input name="duration" type="number" min="0" max="24" step="0.25" required></label><label>Chantier<select name="job"><option value="0">Aucun</option>${jobs.map(j=>`<option value="${j.id}">${esc(j.reference||j.name)}</option>`).join('')}</select></label><label>Équipe<select name="team"><option value="0">Aucune</option>${teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label>Document<input name="document"></label></div><label>Commentaire<textarea name="comment"></textarea></label><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function saveTimeRecord(event,personId){event.preventDefault();const person=getPerson(personId),f=new FormData(event.target);person.timeRecords??=[];person.timeRecords.push({id:'time-'+crypto.randomUUID(),personId,date:f.get('date'),type:f.get('type'),duration:Number(f.get('duration')||0),job:Number(f.get('job')||0),team:Number(f.get('team')||0),document:f.get('document').trim(),comment:f.get('comment').trim()});closeModal();render();showPersonDossier(personId);toast('Temps ou absence enregistré.')}
const showPersonBeforeCompliance=showPersonDossier;showPersonDossier=function(id){showPersonBeforeCompliance(id);const person=getPerson(id),root=document.querySelector('#modalbody .modal-inner');if(!person||!root)return;root.insertAdjacentHTML('beforeend',`<section class="job-detail-section"><div class="section-heading"><div><h3>Certifications & formations</h3><span class="subtle">${(person.certifications||[]).length} entrée(s)</span></div><button class="btn" onclick="certificationForm(${id})">+ Ajouter</button></div>${(person.certifications||[]).map(item=>`<div class="detail-row"><span><strong>${esc(item.type)}</strong><small>${esc(item.provider||'Organisme à compléter')}</small></span><span class="badge ${item.status==='Expirée'?'red':item.status==='À renouveler'?'warn':'green'}">${esc(item.status)}${item.expires?' · '+fullDate(item.expires):''}</span></div>`).join('')||'<p class="person-empty">Aucune certification structurée.</p>'}</section><section class="job-detail-section"><div class="section-heading"><div><h3>EPI remis</h3><span class="subtle">${(person.ppe||[]).length} remise(s)</span></div><button class="btn" onclick="ppeForm(${id})">+ Remise EPI</button></div>${(person.ppe||[]).map(item=>`<div class="detail-row"><span><strong>${esc(item.type)}</strong><small>${fullDate(item.issued)} · ${item.quantity} pièce(s)</small></span><b>${item.returned?'Retourné':'En service'}</b></div>`).join('')||'<p class="person-empty">Aucun EPI enregistré.</p>'}</section><section class="job-detail-section"><div class="section-heading"><div><h3>Temps & absences</h3><span class="subtle">${(person.timeRecords||[]).length} entrée(s)</span></div><button class="btn" onclick="timeRecordForm(${id})">+ Encoder</button></div></section>`)};
